<!doctype html><html lang="en"><meta charset="utf-8"><title>Set up Sweetcron</title><main><h1>Set up Sweetcron</h1><p>Create the first administrator account. Setup closes after this account is created.</p><?php if (! empty($errors)): ?><ul role="alert"><?php foreach ($errors as $error): ?><li><?= esc($error) ?></li><?php endforeach; ?></ul><?php endif; ?><form method="post"><?= csrf_field() ?><label>Site title <input name="title" required maxlength="255" value="<?= old('title') ?>"></label><label>Username <input name="username" required minlength="5" maxlength="60" autocomplete="username" value="<?= old('username') ?>"></label><label>Email <input name="email" type="email" required maxlength="100" value="<?= old('email') ?>"></label><label>Password <input name="password" type="password" required minlength="12" autocomplete="new-password"></label><button>Create site</button></form></main></html>
